class Solution {
public:
    long long maximumValueSum(vector<int>& nums, int k, vector<vector<int>>& edges) {
        long long total = 0;
        vector<long long> diffs;
        for (int x : nums) {
            total += x;
            diffs.push_back((long long)(x ^ k) - x);
        }
        sort(diffs.rbegin(), diffs.rend());
        for (int i = 0; i + 1 < diffs.size(); i += 2) {
            long long gain = diffs[i] + diffs[i + 1];
            if (gain > 0) total += gain;
            else break;
        }
        return total;
    }
};

class Solution {
    public long maximumValueSum(int[] nums, int k, int[][] edges) {
        long total = 0;
        Long[] diffs = new Long[nums.length];
        for (int i = 0; i < nums.length; i++) {
            total += nums[i];
            diffs[i] = (long)(nums[i] ^ k) - nums[i];
        }
        Arrays.sort(diffs, Collections.reverseOrder());
        for (int i = 0; i + 1 < diffs.length; i += 2) {
            long gain = diffs[i] + diffs[i + 1];
            if (gain > 0) total += gain;
            else break;
        }
        return total;
    }
}

